"""Adds our native code and settings to the project generated by `tauri android init`."""

import pathlib
import shutil
import sys

app = pathlib.Path(sys.argv[1]) / "src-tauri" / "gen" / "android" / "app"
here = pathlib.Path(__file__).parent


def replace_once(path, old, new):
    text = path.read_text()
    if old not in text:
        sys.exit(f"patch.py: {old!r} not found in {path}")
    path.write_text(text.replace(old, new, 1))


java = app / "src/main/java/org/goofyfiles/chat"
for name in ("MainActivity.kt", "ChatService.kt", "BootReceiver.kt", "Updater.kt"):
    shutil.copy(here / name, java / name)

manifest = app / "src/main/AndroidManifest.xml"
permissions = "".join(
    f'<uses-permission android:name="android.permission.{p}" />\n    '
    for p in (
        "CAMERA",
        "RECORD_AUDIO",
        "MODIFY_AUDIO_SETTINGS",
        "POST_NOTIFICATIONS",
        "FOREGROUND_SERVICE",
        "FOREGROUND_SERVICE_SPECIAL_USE",
        "VIBRATE",
        "FOREGROUND_SERVICE_MICROPHONE",
        "FOREGROUND_SERVICE_CAMERA",
        "REQUEST_IGNORE_BATTERY_OPTIMIZATIONS",
        "RECEIVE_BOOT_COMPLETED",
        "REQUEST_INSTALL_PACKAGES",
    )
)
features = "".join(
    f'<uses-feature android:name="android.hardware.{f}" android:required="false" />\n    '
    for f in ("camera", "microphone")
)
replace_once(manifest, "<application", permissions + features + "<application")
service = """    <service
            android:name=".ChatService"
            android:exported="false"
            android:foregroundServiceType="specialUse|microphone|camera">
            <property
                android:name="android.app.PROPERTY_SPECIAL_USE_FGS_SUBTYPE"
                android:value="Self-hosted chat: keeps a connection to receive messages and calls" />
        </service>
        <receiver android:name=".BootReceiver" android:exported="false">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED" />
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED" />
            </intent-filter>
        </receiver>
        <receiver android:name=".InstallReceiver" android:exported="false" />
    </application>"""
replace_once(manifest, "</application>", service)

gradle = app / "build.gradle.kts"
replace_once(gradle, "dependencies {", 'dependencies {\n    implementation("com.squareup.okhttp3:okhttp:4.12.0")')
